import {chinaDate} from './cloud-contract.mjs';
import {signedCostMoney} from './cost-sources-contract.mjs';
const decimal=n=>Math.floor(Number(n)/100)+'.'+String(Number(n)%100).padStart(2,'0');
export function createCashEditors({api,h,mount,input,area}){
 async function cashMovement(direction='in',id=null){
  const state=id?await api.cashMovement(id):null,r=state?.record,key=crypto.randomUUID();if(r?.status==='void')throw Error('这条资金记录已经作废。');direction=r?.direction||direction;const kind=direction==='in'?'income':'expense';
  let selected=(state?.matches||[]).map(m=>({source:m.current||m.line.snapshot,key:m.line.key,amount:decimal(m.line.amountCents),changed:m.sourceChanged||m.overmatched})),page=0,results=[],busy=false,stopped=false,request;
  const body=(r?`<p>${h(r.accountLabel)} · ${h(r.sourceReference)} · ${direction==='in'?'到账':'付款'}</p>`:input('accountLabel','账户或渠道名称（可用简称）','','required maxlength="100"')+input('sourceReference','银行／平台流水编号（同账户下不重复）','','required maxlength="200"'))+
   input('paidDate',direction==='in'?'实际到账日期':'实际付款日期',r?.paidDate||chinaDate(),'required type="date"')+input('amount','本次实际金额（元）',r?decimal(r.amountCents):'','required inputmode="decimal" maxlength="11"')+input('description','事项说明',r?.description,'required maxlength="500"')+
   '<h3>对应原来源</h3><p class="muted">可分次、跨月或对应多笔来源，也可暂不对应。只保存资金事实，不新增收入、费用或报销。个人垫付请从原结算单登记报销，已有报销付款自动列示。</p><div data-cash-selected></div>'+`<div class="module-toolbar"><label>原来源月份<input type="month" data-cash-source-month value="${h(chinaDate().slice(0,7))}" min="1900-01" max="2199-12"></label><label>查找原来源<input data-cash-source-q maxlength="100" placeholder="${direction==='in'?'店铺':'支出事项'}"></label><button type="button" class="secondary" data-cash-source-search>查找</button></div><p class="muted">${direction==='in'?'到账对应已确认月度收入。差额不自动视为少收、退款或手续费。':'公司付款对应原“公司支付”支出，累计对应额不得超过原支出。'}</p><div data-cash-candidates></div><div class="pager"><button type="button" class="secondary" data-cash-source-prev>上一页</button><span data-cash-source-caption></span><button type="button" class="secondary" data-cash-source-next>下一页</button></div>`+area('reason',r?'修正及重新核对依据（必填）':'登记依据（必填）');
  mount((r?'修正':'登记')+(direction==='in'?'实际到账':'公司付款'),body,f=>{
   const lines=selected.map(l=>({kind,storeId:kind==='income'?l.source.storeId:null,month:kind==='income'?l.source.month:null,expenseId:kind==='expense'?l.source.expenseId:null,sourceVersion:l.source.version,amount:l.amount}));
   const value={requestKey:key,paidDate:f.get('paidDate'),amount:f.get('amount').trim(),description:f.get('description'),reason:f.get('reason'),lines};
   return api.saveCashMovement(id,r?{...value,expectedVersion:r.version}:{...value,direction,accountLabel:f.get('accountLabel'),sourceReference:f.get('sourceReference')});
  },{kind:'cash-movement',id},()=>api.cashReceipt(key,id?'revise':'create',id),form=>{
   const $=q=>form.querySelector(q),dirty=()=>form.dispatchEvent(new Event('input',{bubbles:true}));
   const render=()=>{$('[data-cash-selected]').innerHTML=selected.map((l,i)=>`<article class="observation"><b>${h(l.source.label)}${l.source.month?' · '+h(l.source.month):''}</b><p>原金额 ${h(signedCostMoney(String(l.source.amountCents)))}${l.changed?' · 原来源或累计对应有变化，请重新核对':''}</p><label>本次对应金额（元）<input data-cash-line="${i}" value="${h(l.amount)}" required inputmode="decimal" maxlength="11"></label><button type="button" class="text-button" data-cash-remove="${i}">取消这项对应</button></article>`).join('')||'<p class="muted">尚未选择来源，本笔金额将保留为暂未对应。</p>';};
   const load=async()=>{request?.abort();request=new AbortController();const signal=request.signal;busy=true;$('[data-cash-candidates]').textContent='正在查找原来源…';$('[data-cash-source-prev]').disabled=true;$('[data-cash-source-next]').disabled=true;try{const d=await api.cashSources({kind,month:$('[data-cash-source-month]').value,q:$('[data-cash-source-q]').value.trim(),offset:page},signal);if(stopped||signal.aborted)return;results=d.rows;$('[data-cash-candidates]').innerHTML=results.map((s,i)=>`<button type="button" class="account-row" data-cash-add="${i}"><span><b>${h(s.label)}</b><small>${h(s.month)} · 原金额 ${h(signedCostMoney(String(s.amountCents)))} · 累计对应 ${h(signedCostMoney(s.cashCents))}</small></span><span>选择 ›</span></button>`).join('')||'<p class="muted">暂无匹配的有效原来源，请先确认收入或记录公司支出。</p>';$('[data-cash-source-caption]').textContent=`${d.total} 条来源`;$('[data-cash-source-prev]').disabled=page===0;$('[data-cash-source-next]').disabled=page+50>=d.total;}catch(e){if(!stopped&&e.name!=='AbortError')$('[data-cash-candidates]').textContent=e.message;}finally{busy=false;}};
   const click=e=>{if(form.querySelector('[type=submit]').disabled)return;const add=e.target.closest('[data-cash-add]'),remove=e.target.closest('[data-cash-remove]');if(add&&!busy){const s=results[Number(add.dataset.cashAdd)];if(!selected.some(l=>l.key===s.key)&&selected.length<50){selected.push({source:s,key:s.key,amount:'',changed:false});render();dirty();}}if(remove){selected.splice(Number(remove.dataset.cashRemove),1);render();dirty();}if(e.target.closest('[data-cash-source-search]')){page=0;load();}if(e.target.closest('[data-cash-source-prev]')){page=Math.max(0,page-50);load();}if(e.target.closest('[data-cash-source-next]')){page+=50;load();}};
   const change=e=>{if(e.target.matches('[data-cash-line]'))selected[Number(e.target.dataset.cashLine)].amount=e.target.value.trim();};
   form.addEventListener('click',click);form.addEventListener('input',change);render();load();return ()=>{stopped=true;request?.abort();form.removeEventListener('click',click);form.removeEventListener('input',change);};
  });
 }
 async function cashVoid(id){const {record:r}=await api.cashMovement(id),key=crypto.randomUUID();if(r.status==='void')throw Error('这条记录已经作废。');mount('作废资金记录',`<p>${h(r.description)} · ${h(signedCostMoney(String(r.amountCents)))}</p><p>保留原历史，移出有效资金合计并解除当前金额对应；收入、支出和报销记录保持原事实。</p>`+area('reason','作废原因（必填）'),f=>api.voidCashMovement(id,{requestKey:key,expectedVersion:r.version,reason:f.get('reason')}),{kind:'cash-movement',id},()=>api.cashReceipt(key,'void',id));}
 return {cashMovement,cashVoid};
}
